27	  const [pageType, setPageType] = useState<PageType>(
28	    (searchParams.get("type") as PageType) || "landing"
29	  );
30	  const [isAnalyzing, setIsAnalyzing] = useState(false);
31	  const [currentStep, setCurrentStep] = useState(-1);
32	
33	  const totalSteps = SCAN_STEPS.length;
34	  const progressPercent =
35	    currentStep < 0 ? 0 : Math.round(((currentStep + 1) / totalSteps) * 100);
36	
37	  const startAnalysis = useCallback(() => {
38	    if (!url.trim()) return;
39	    setIsAnalyzing(true);
40	    setCurrentStep(0);
41	  }, [url]);
42	
43	  // Auto-start if URL comes from query params
44	  useEffect(() => {
45	    if (searchParams.get("url") && !isAnalyzing) {
46	      // Don't auto-start, just prefill
47	    }
48	  }, [searchParams, isAnalyzing]);
49	
50	  // Step progression
51	  useEffect(() => {
52	    if (!isAnalyzing || currentStep < 0) return;
53	
54	    if (currentStep >= totalSteps) {
