56	      const timer = setTimeout(() => {
57	        navigate("/reports/scan_001");
58	      }, 800);
59	      return () => clearTimeout(timer);
60	    }
61	
62	    const timer = setTimeout(() => {
63	      setCurrentStep((prev) => prev + 1);
64	    }, 1200);
65	
66	    return () => clearTimeout(timer);
67	  }, [isAnalyzing, currentStep, totalSteps, navigate]);
68	
