137	                <Select value={pageType} onValueChange={(v) => setPageType(v as PageType)}>
138	                  <SelectTrigger className="h-12 rounded-xl border-slate-200 bg-white">
139	                    <SelectValue placeholder="Select page type" />
140	                  </SelectTrigger>
141	                  <SelectContent>
142	                    {PAGE_TYPES.map((type) => (
143	                      <SelectItem key={type.value} value={type.value}>
144	                        {type.label}
145	                      </SelectItem>
146	                    ))}
147	                  </SelectContent>
148	                </Select>
149	              </div>
