1	import { useEffect, useState } from "react";
2	import { getScoreHex, getScoreLabel } from "@/lib/score-utils";
3	import { cn } from "@/lib/utils";
4	
5	interface ScoreRingProps {
6	  score: number;
7	  size?: number;
8	  strokeWidth?: number;
9	  showLabel?: boolean;
10	  className?: string;
11	}
12	
13	export function ScoreRing({
14	  score,
15	  size = 120,
16	  strokeWidth = 8,
17	  showLabel = true,
18	  className,
19	}: ScoreRingProps) {
20	  const [animatedOffset, setAnimatedOffset] = useState(0);
21	  const radius = (size - strokeWidth) / 2;
22	  const circumference = 2 * Math.PI * radius;
23	  const targetOffset = circumference * (1 - score / 100);
24	
25	  useEffect(() => {
26	    // Start from full offset (empty circle) and animate to target
27	    setAnimatedOffset(circumference);
28	    const timer = setTimeout(() => setAnimatedOffset(targetOffset), 50);
29	    return () => clearTimeout(timer);
30	  }, [score, circumference, targetOffset]);
31	
32	  const color = getScoreHex(score);
33	  const label = getScoreLabel(score);
34	  const center = size / 2;
35	  const fontSize = size * 0.3;
36	  const labelSize = size * 0.1;
37	
38	  return (
39	    <div className={cn("relative inline-flex flex-col items-center", className)}>
40	      <svg width={size} height={size} className="transform -rotate-90">
41	        {/* Background circle */}
42	        <circle
43	          cx={center}
44	          cy={center}
45	          r={radius}
46	          fill="none"
47	          stroke="currentColor"
48	          strokeWidth={strokeWidth}
49	          className="text-slate-100"
50	        />
51	        {/* Score circle */}
52	        <circle
53	          cx={center}
54	          cy={center}
55	          r={radius}
56	          fill="none"
57	          stroke={color}
58	          strokeWidth={strokeWidth}
59	          strokeLinecap="round"
60	          strokeDasharray={circumference}
61	          strokeDashoffset={animatedOffset}
62	          style={{ transition: "stroke-dashoffset 1s ease-out" }}
63	        />
64	      </svg>
65	      {/* Score number centered */}
66	      <div className="absolute inset-0 flex flex-col items-center justify-center">
67	        <span
68	          className="font-bold text-foreground"
69	          style={{ fontSize: `${fontSize}px`, lineHeight: 1 }}
70	        >
71	          {score}
72	        </span>
73	        <span
74	          className="text-muted-foreground"
75	          style={{ fontSize: `${labelSize}px` }}
76	        >
77	          /100
78	        </span>
79	      </div>
80	      {showLabel && (
81	        <span
82	          className="mt-1.5 text-xs font-medium"
83	          style={{ color }}
84	        >
85	          {label}
86	        </span>
87	      )}
88	    </div>
89	  );
90	}
