55	            ) : (
56	              <TrendingDown className="h-3.5 w-3.5 text-red-500" />
57	            )}
58	            <span
59	              className={cn(
60	                "text-xs font-medium",
61	                isPositiveTrend ? "text-green-600" : "text-red-600"
62	              )}
63	            >
